<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ejecutarAccion, listarBandeja, type BandejaFilters } from '../services/bandejas'
import type { BandejaTipo, CatalogOption, HistorialDocumento } from '../../interfaces/documento'

const props = defineProps<{ tipo: BandejaTipo; title: string; description: string; accent?: string }>()
const filters = reactive<BandejaFilters>({ criterio:'', codigo_unico:'', tipo_documento_id:0, instancia_id:0, page:1 })
const items = ref<HistorialDocumento[]>([]), tipos = ref<CatalogOption[]>([]), instancias = ref<CatalogOption[]>([])
const context = reactive<{ instancia?: CatalogOption|null; cargo?: CatalogOption|null }>({})
const pagination = reactive({ current:1,last:1,total:0,perPage:15 })
const loading=ref(false), actionLoading=ref(false), error=ref(''), success=ref('')
const selected=ref<number[]>([]), detail=ref<HistorialDocumento|null>(null), rejectOpen=ref(false), rejectReason=ref('')
const allSelected=computed(()=>items.value.length>0&&items.value.every(i=>selected.value.includes(i.id)))
const canSelect=computed(()=>['por-recepcionar','en-bandeja','archivados'].includes(props.tipo))

async function load(page=1){filters.page=page;loading.value=true;error.value='';selected.value=[];try{const r=await listarBandeja(props.tipo,filters);items.value=r.data;tipos.value=r.filtros.tipos_documento;instancias.value=r.filtros.instancias;context.instancia=r.contexto.instancia_activa;context.cargo=r.contexto.cargo_activo;Object.assign(pagination,{current:r.current_page,last:r.last_page,total:r.total,perPage:r.per_page})}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo cargar la bandeja.'}finally{loading.value=false}}
function clear(){Object.assign(filters,{criterio:'',codigo_unico:'',tipo_documento_id:0,instancia_id:0});void load()}
function toggleAll(){selected.value=allSelected.value?[]:items.value.map(i=>i.id)}
function toggle(id:number){selected.value=selected.value.includes(id)?selected.value.filter(x=>x!==id):[...selected.value,id]}
async function action(name:string, ids=selected.value, payload:Record<string,unknown>={}){if(!ids.length)return;actionLoading.value=true;error.value='';try{await ejecutarAccion(name,ids,payload);success.value='Operación realizada correctamente.';rejectOpen.value=false;rejectReason.value='';await load(filters.page)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo completar la operación.'}finally{actionLoading.value=false}}
function displayNumber(i:HistorialDocumento){return i.documento.numero_completo||i.documento.numero||`Documento #${i.documento_id}`}
function date(value?:string|null){return value?new Intl.DateTimeFormat('es-PE',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'—'}
onMounted(()=>load())
</script>

<template>
<div class="inbox" :style="{'--accent':accent||'#2878d0'}">
  <nav class="breadcrumbs"><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/tramite">Trámite V2</RouterLink> / <RouterLink to="/modulos/tramite/bandejas">Bandejas</RouterLink> / {{title}}</nav>
  <header class="page-header"><div class="icon">TR</div><div><small>E‑Trámi V2</small><h1>{{title}}</h1><p>{{description}}</p></div><div v-if="context.instancia" class="context"><b>{{context.instancia.nombre}}</b><span>{{context.cargo?.nombre||'Cargo activo'}}</span></div><strong v-if="pagination.total">{{pagination.total}} documentos</strong></header>
  <div v-if="success" class="flash"><b>✓</b>{{success}}<button @click="success=''">×</button></div>
  <form class="filters" @submit.prevent="load()"><div class="filter-title"><b>⌕ Buscar documentos</b><small>Número, asunto, código único, tipo u oficina relacionada.</small></div><div class="filter-grid"><label class="wide"><span>Criterio</span><input v-model.trim="filters.criterio" placeholder="Número o asunto del documento"></label><label><span>Código único</span><input v-model.trim="filters.codigo_unico" placeholder="Código único"></label><label><span>Tipo documental</span><select v-model="filters.tipo_documento_id"><option :value="0">Todos</option><option v-for="o in tipos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label><span>Instancia</span><select v-model="filters.instancia_id"><option :value="0">Todas</option><option v-for="o in instancias" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label></div><div class="filter-actions"><button type="submit">Buscar</button><button type="button" class="clear" @click="clear">Limpiar</button></div></form>

  <div v-if="canSelect&&selected.length" class="bulk"><b>{{selected.length}} seleccionados</b><button v-if="tipo==='por-recepcionar'" :disabled="actionLoading" @click="action('recepcionar',selected)">Recepcionar</button><button v-if="tipo==='por-recepcionar'" class="danger" @click="rejectOpen=true">Rechazar</button><button v-if="tipo==='en-bandeja'" :disabled="actionLoading" @click="action('archivar',selected)">Archivar</button><button v-if="tipo==='archivados'" :disabled="actionLoading" @click="action('recuperar',selected)">Recuperar</button></div>
  <div v-if="error" class="notice error"><b>No se pudo obtener la bandeja.</b><span>{{error}}</span><button @click="load(filters.page)">Reintentar</button></div><div v-else-if="loading" class="notice"><span class="spinner"></span>Cargando documentos…</div><div v-else-if="!items.length" class="notice"><b>No hay documentos en esta bandeja</b><span>Modifica los criterios de búsqueda o actualiza la bandeja.</span></div>

  <section v-else class="table-wrap"><table><thead><tr><th v-if="canSelect"><input type="checkbox" :checked="allSelected" @change="toggleAll"></th><th>Documento</th><th>Asunto</th><th>Origen / destino</th><th>Estado</th><th>Fecha</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td v-if="canSelect"><input type="checkbox" :checked="selected.includes(item.id)" @change="toggle(item.id)"></td><td><b>{{displayNumber(item)}}</b><small>{{item.documento.tipo_documento?.nombre||'Sin tipo'}} · CU {{item.codigounico||'—'}}</small><em v-if="item.documento.es_externo">Externo</em></td><td><span class="subject">{{item.documento.asunto||'Sin asunto'}}</span><small v-if="item.proveido">{{item.proveido}}</small></td><td><span>{{item.instancia_origen?.nombre||'—'}}</span><small>→ {{item.instancia_destino?.nombre||'—'}}</small><small>{{item.cargo_origen?.nombre||item.usuario_origen?.nombre||''}}</small></td><td><span class="status">{{item.estado}}</span><small>{{item.tipo_tramite||''}}</small></td><td>{{date(item.fecha_recepcion||item.created_at)}}</td><td><button class="detail" @click="detail=item">Ver detalle</button></td></tr></tbody></table></section>
  <footer v-if="pagination.last>1" class="pagination"><button :disabled="pagination.current===1" @click="load(pagination.current-1)">Anterior</button><span>Página {{pagination.current}} de {{pagination.last}}</span><button :disabled="pagination.current===pagination.last" @click="load(pagination.current+1)">Siguiente</button></footer>

  <div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal"><header><div class="modal-icon">TR</div><div><small>Documento #{{detail.documento_id}}</small><h2>{{displayNumber(detail)}}</h2></div><button @click="detail=null">×</button></header><div class="detail-body"><h3>{{detail.documento.asunto}}</h3><dl><div><dt>Código único</dt><dd>{{detail.codigounico||'—'}}</dd></div><div><dt>Tipo</dt><dd>{{detail.documento.tipo_documento?.nombre||'—'}}</dd></div><div><dt>Estado</dt><dd>{{detail.estado}}</dd></div><div><dt>Origen</dt><dd>{{detail.instancia_origen?.nombre||'—'}}</dd></div><div><dt>Destino</dt><dd>{{detail.instancia_destino?.nombre||'—'}}</dd></div><div><dt>Fecha</dt><dd>{{date(detail.created_at)}}</dd></div><div><dt>Referencia</dt><dd>{{detail.documento.referencia||'—'}}</dd></div><div><dt>Observación</dt><dd>{{detail.observacion||detail.indicacion||'—'}}</dd></div></dl><p>El seguimiento completo, anexos y archivos se habilitarán en la etapa de detalle documental.</p></div></section></div>
  <div v-if="rejectOpen" class="backdrop" @mousedown.self="rejectOpen=false"><section class="modal small-modal"><header><div><small>Acción documentaria</small><h2>Rechazar documentos</h2></div><button @click="rejectOpen=false">×</button></header><div class="detail-body"><label><span>Motivo del rechazo</span><textarea v-model.trim="rejectReason" rows="4" placeholder="Indique el motivo"></textarea></label><footer><button class="cancel" @click="rejectOpen=false">Cancelar</button><button class="danger" :disabled="!rejectReason||actionLoading" @click="action('rechazar',selected,{motivo:rejectReason})">Confirmar rechazo</button></footer></div></section></div>
</div>
</template>

<style scoped>
.inbox{color:#35454d}.breadcrumbs{margin-bottom:17px;color:#98a4aa;font-size:.7rem}.breadcrumbs a{color:var(--accent);text-decoration:none}.page-header{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff;box-shadow:0 5px 20px #2b45530d}.icon,.modal-icon{display:grid;place-items:center;flex:none;border-radius:11px;color:#fff;background:var(--accent);font-weight:700}.icon{width:52px;height:52px}.modal-icon{width:42px;height:42px}.page-header small,.modal small{color:var(--accent);font-size:.65rem;font-weight:700;text-transform:uppercase}.page-header h1{margin:2px 0;font-size:1.38rem}.page-header p{margin:0;color:#7d898f;font-size:.72rem}.page-header>strong{margin-left:10px;padding:7px 10px;border-radius:20px;color:var(--accent);background:#edf4fc;font-size:.65rem}.context{margin-left:auto;text-align:right}.context b,.context span{display:block}.context b{font-size:.7rem}.context span{color:#89959b;font-size:.62rem}.flash{margin:14px 0 -1px;padding:11px 13px;display:flex;gap:8px;border:1px solid #badfce;border-radius:8px;color:#246c50;background:#eff9f4;font-size:.7rem}.flash button{margin-left:auto;border:0;background:none}.filters{margin:16px 0;padding:20px;border:1px solid #e4e9ed;border-radius:11px;background:#fff}.filter-title b,.filter-title small{display:block}.filter-title b{font-size:.83rem}.filter-title small{color:#89959b;font-size:.64rem}.filter-grid{margin-top:14px;display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;gap:11px}label>span{display:block;margin-bottom:6px;color:#65727a;font-size:.65rem;font-weight:600}input,select,textarea{width:100%;border:1px solid #dce3e7;border-radius:7px;outline:0;background:#fff;font:inherit;font-size:.7rem}input,select{height:40px;padding:0 11px}textarea{padding:10px;resize:vertical}input:focus,select:focus,textarea:focus{border-color:var(--accent);box-shadow:0 0 0 3px #2878d014}.filter-actions{margin-top:15px;display:flex;gap:7px}.filter-actions button,.bulk button,.notice button,.pagination button{padding:8px 14px;border:1px solid var(--accent);border-radius:7px;color:#fff;background:var(--accent);font-size:.66rem;font-weight:600}.filter-actions .clear,.cancel{color:#66737a;border-color:#d7dfe3;background:#fff}.bulk{margin-bottom:12px;padding:10px 13px;display:flex;align-items:center;gap:7px;border-radius:9px;color:#3e4d55;background:#eaf2fb;font-size:.68rem}.bulk b{margin-right:auto}.danger{border-color:#bd5050!important;background:#bd5050!important;color:#fff!important}.notice{min-height:140px;padding:25px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:8px;border:1px dashed #ccd6dc;border-radius:10px;color:#748188;background:#fff;font-size:.72rem}.notice.error{color:#9d3b3b;border-color:#efcaca}.spinner{width:24px;height:24px;border:2px solid #d2e1f1;border-top-color:var(--accent);border-radius:50%;animation:spin .7s linear infinite}.table-wrap{overflow:auto;border:1px solid #e0e6ea;border-radius:11px;background:#fff}table{width:100%;border-collapse:collapse;min-width:950px}th{padding:11px 12px;color:#75828a;background:#f5f7f9;text-align:left;font-size:.61rem;text-transform:uppercase}td{padding:12px;border-top:1px solid #edf0f2;vertical-align:top;font-size:.67rem}td b,td span,td small{display:block}td small{margin-top:3px;color:#89959b;font-size:.59rem}td em{display:inline-block;margin-top:5px;padding:3px 5px;border-radius:4px;color:#925b1a;background:#fff0d7;font-size:.55rem;font-style:normal}.subject{max-width:310px;line-height:1.5}.status{display:inline-block;padding:4px 6px;border-radius:12px;color:var(--accent);background:#edf4fc;font-size:.58rem;font-weight:700}.detail{padding:7px 10px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.61rem}.pagination{padding:18px;display:flex;justify-content:center;align-items:center;gap:13px}.pagination span{font-size:.67rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,680px);max-height:calc(100vh - 40px);overflow:auto;border-radius:13px;background:#fff;box-shadow:0 20px 65px #10223655}.small-modal{max-width:470px}.modal>header{padding:18px 20px;display:flex;align-items:center;gap:11px;border-bottom:1px solid #e8edf0}.modal h2{margin:2px 0;font-size:1.03rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.detail-body{padding:20px}.detail-body h3{margin:0 0 15px;font-size:.9rem}.detail-body dl{display:grid;grid-template-columns:1fr 1fr;gap:0 25px;margin:0}.detail-body dl>div{padding:7px 0;display:flex;justify-content:space-between;gap:10px;border-bottom:1px solid #edf0f2;font-size:.65rem}.detail-body dt{color:#849098}.detail-body dd{margin:0;text-align:right}.detail-body>p{margin:18px 0 0;padding:11px;border-radius:7px;color:#77858c;background:#f5f7f8;font-size:.63rem}.detail-body footer{margin-top:16px;display:flex;justify-content:flex-end;gap:7px}.detail-body footer button{padding:9px 13px;border:1px solid #d7dfe3;border-radius:7px;font-size:.66rem}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:900px){.filter-grid{grid-template-columns:1fr 1fr}.page-header{flex-wrap:wrap}.context{margin-left:0;text-align:left}.page-header>strong{margin-left:auto}}@media(max-width:600px){.filter-grid,.detail-body dl{grid-template-columns:1fr}.page-header>strong{display:none}.context{width:100%}.bulk{flex-wrap:wrap}.bulk b{width:100%}}
</style>
